//! Generated Watcher cards use the same construction law as their M25 constructor, so a card that is
//! regenerated by a shared owner keeps its own setup. Example: the card Stasis returns keeps Exhaust.
use super::super::*;
use crate::{content::{CardId, Character, EncounterId}, items::CombatItemContext};

#[test]
fn m25_generated_watcher_kinds_match_their_m25_constructor() {
    for row in crate::content::Catalog::standard().cards() {
        if row.id == CardId::Miracle || !crate::content::watcher::supports_m25_generated(row.id) { continue }
        for upgrades in 0..=1 {
            let generated = card_state::generated(row.id, CardInstanceId(7), upgrades)
                .unwrap_or_else(|| panic!("{:?}+{upgrades} generated constructor", row.id));
            let reference = m25_watcher_live_card(row.id, CardInstanceId(7), upgrades).unwrap();
            assert_eq!(generated.local, reference.local, "{:?}+{upgrades} combat-local fields", row.id);
        }
    }
    for upgrades in 0..=1 {
        assert!(card_state::generated(CardId::TalkToTheHand, CardInstanceId(7), upgrades).unwrap().local.exhaust_on_finish,
            "Talk to the Hand exhausts (base and upgraded)");
    }
}

#[test]
fn m25_stasis_returns_talk_to_the_hand_with_exhaust() {
    let mut entry = super::m6_ordinary::entry(EncounterId::BronzeAutomaton);
    entry.setup.character = Character::Watcher;
    entry.setup.player.hp = 300;
    entry.setup.player.max_hp = 300;
    entry.cards = vec![m25_watcher_live_card(CardId::TalkToTheHand, CardInstanceId(1), 0).unwrap()];
    entry.opening_draw = 0;
    let mut items = Some(CombatItemContext::new(vec![], vec![None; 3]).with_m25_profile());
    let mut c = Combat::enter_with_item_context(entry, &mut items).expect("Watcher Bronze Automaton combat enters");
    let boss = Actor::Enemy(c.state.enemies[0].instance_id.clone());
    c.enqueue_native_effects(vec![Effect { source: Source::Actor(boss.clone()), target: Some(boss), kind: EffectKind::EnemyMove }], None).unwrap();
    assert_eq!(c.state.enemies.len(), 3, "Bronze Automaton spawned its orbs");

    super::m6_stasis::capture(&mut c, 1);
    let orb = c.state.enemies[1].instance_id.clone();
    assert_eq!(c.state.stasis[&orb].full().unwrap().id, CardId::TalkToTheHand);

    super::m5_elites::hit(&mut c, 1, 100);
    assert!(c.state.stasis.is_empty());
    let returned = c.state.piles.hand.iter().find(|card| card.full().unwrap().instance == CardInstanceId(1)).expect("returned to hand");
    assert!(returned.full().unwrap().local.exhaust_on_finish, "the returned Talk to the Hand keeps Exhaust");
    assert!(c.public_full().is_ok());
}
